import { test, expect } from '@playwright/test';

test.describe('Error Boundary Tests', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/'); // Replace with the actual URL of the application
  });

  test('should display fallback screen on UI crash', async ({ page }) => {
    // Simulate a UI crash
    await page.evaluate(() => {
      throw new Error('Simulated UI crash');
    });

    // Check for the presence of the fallback screen
    const fallbackScreen = page.getByText('Something went wrong. Please try again later.');
    await expect(fallbackScreen).toBeVisible();
  });

  test('should not show fallback screen when UI is functioning', async ({ page }) => {
    // Interact with the UI to ensure it's functioning
    await page.getByRole('button', { name: 'Load Data' }).click();

    // Check that the fallback screen is not visible
    const fallbackScreen = page.getByText('Something went wrong. Please try again later.');
    await expect(fallbackScreen).not.toBeVisible();
  });
});
